import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { initializeDatabase } from '../../src/data/migrations.ts';
import { createRepositories } from '../../src/data/repositories.ts';
import { adapt } from '../sqlite.mjs';

const [path, phase, expected] = process.argv.slice(2);
let networkCalls = 0;
globalThis.fetch = async () => { networkCalls++; throw new Error('Network disabled for offline verification.'); };
const sqlite = new DatabaseSync(path);
try {
  const db = adapt(sqlite); await initializeDatabase(db);
  const now = () => phase === 'write' ? '2026-10-14T15:30:00.000Z' : '2026-10-16T12:00:00.000Z';
  const r = createRepositories(db, randomUUID, now);
  const date = '2026-10-15';
  const input = { date, meal: 'breakfast', quantity: 1.5, quantity_mode: 'servings' };
  if (phase === 'write') {
    assert.equal(await r.profiles.get(), null);
    assert.equal((await r.dashboard.getDay(date)).progress, null);
    assert.ok((await r.foods.search('')).some((food) => food.source === 'bundled'));
    const profile = { sex: 'male', age: 30, height_cm: 180, current_weight_kg: 80, target_weight_kg: 80, activity_level: 'sedentary', goal: 'maintain', manual_calorie_target: 2100 };
    const profileId = await r.profiles.saveCalorieProfile(profile);
    const food = { name: 'Journey test oats', calories: 200, serving_amount: 50, serving_unit: 'g', protein: 10, notes: 'Invented automated-test values only.' };
    const foodId = await r.foods.createCustom(food);
    const diaryId = await r.diary.addEntry(foodId, input);
    assert.equal((await r.dashboard.getDay(date)).totals.total, 300);
    await r.diary.update(diaryId, { ...input, quantity: 2 });
    const deletedId = await r.diary.addEntry(foodId, { ...input, meal: 'snacks' });
    await r.diary.remove(deletedId); assert.equal(await r.diary.get(deletedId), null);
    const planId = await r.plans.addEntry(foodId, { ...input, date: '2026-10-16', meal: 'lunch', quantity: 3 });
    await r.plans.update(planId, { ...input, date: '2026-10-16', meal: 'lunch', quantity: 2 });
    assert.equal((await r.dashboard.getDay(date)).totals.total, 400);
    assert.equal(await r.plans.copyDay('2026-10-16', '2026-10-17'), 1);
    const copyId = (await r.plans.listDay('2026-10-17'))[0].id;
    await r.foods.updateCustom(foodId, { ...food, calories: 300, name: 'Edited journey oats' });
    assert.equal((await r.foods.search('Edited journey'))[0].calories, 300);
    assert.equal((await r.diary.get(diaryId)).total_calories, 400);
    assert.equal((await r.plans.get(copyId)).total_calories, 400);
    await r.foods.remove(foodId); assert.equal((await r.foods.search('Edited journey')).length, 0);
    assert.equal(await r.plans.markMealEaten('2026-10-16', 'lunch', date), 1);
    assert.equal(await r.plans.markMealEaten('2026-10-16', 'lunch', date), 0);
    assert.equal((await r.dashboard.getDay(date)).totals.total, 800);
    const weightId = await r.weights.create(date, 79.4);
    await r.weights.update(weightId, date, 79.25);
    const discardedWeight = await r.weights.create('2026-10-14', 79.8);
    await r.weights.remove(discardedWeight);
    const savedFoodId = await r.foods.createCustom({ ...food, name: 'Persistent test apple', calories: 95, serving_amount: 1, serving_unit: 'piece' });
    assert.equal(await r.profiles.saveCalorieProfile({ ...profile, age: 31, manual_calorie_target: 2200 }), profileId);
    assert.equal((await r.profiles.get()).current_weight_kg, 80);
    process.stdout.write(JSON.stringify({ profileId, diaryId, planId, copyId, weightId, savedFoodId }));
  } else {
    const ids = JSON.parse(expected);
    assert.equal((await r.profiles.get()).id, ids.profileId);
    assert.equal((await r.profiles.get()).age, 31);
    assert.equal((await r.profiles.get()).current_weight_kg, 80);
    assert.equal((await r.foods.search('Persistent test'))[0].id, ids.savedFoodId);
    assert.equal((await r.diary.get(ids.diaryId)).entry_date, date);
    assert.equal((await r.diary.get(ids.diaryId)).name, 'Journey test oats');
    assert.equal((await r.diary.get(ids.diaryId)).food_id, null);
    const dashboard = await r.dashboard.getDay(date);
    assert.equal(dashboard.totals.total, 800); assert.equal(dashboard.progress.remaining, 1400);
    assert.equal((await r.diary.listDay('2026-10-14')).length, 0);
    assert.equal((await r.diary.listDay('2026-10-16')).length, 0);
    assert.equal((await r.plans.get(ids.planId)).eaten_date, date);
    assert.equal((await r.plans.get(ids.copyId)).eaten_at, null);
    assert.equal((await r.plans.get(ids.copyId)).quantity, 2);
    assert.equal(await r.plans.markMealEaten('2026-10-16', 'lunch', date), 0);
    assert.equal((await r.diary.listDay(date)).length, 2);
    assert.equal((await r.weights.get(ids.weightId)).weight_kg, 79.25);
    const history = await r.history.getPeriod(date, 'week');
    const recordedDay = history.days.find((day) => day.date === date);
    assert.equal(recordedDay.weight, 79.25); assert.equal(recordedDay.target, 2200);
    assert.equal(recordedDay.consumed, 800); assert.equal(recordedDay.status, 'under');
    assert.equal(history.summary.totalCalories, 800);
    assert.equal((await r.history.getPeriod(date, 'month')).summary.measurements, 1);
    assert.deepEqual(await db.getAllAsync('PRAGMA foreign_key_check'), []);
    assert.equal((await db.getFirstAsync('PRAGMA quick_check')).quick_check, 'ok');
    process.stdout.write('verified');
  }
  assert.equal(networkCalls, 0);
} finally { sqlite.close(); }
